      { "x": 8, "y": 9 },
      { "x": 9, "y": 10 }
    ];

    var kmeans = ml5.kmeans(data, 3, function() {
      var clusters = kmeans.getClusters();
      var newData = [];
      for (var i = 0; i < clusters.length; i++) {
        for (var j = 0; j < clusters[i].length; j++) {
          newData.push({
            "x": clusters[i][j][0],
            "y": clusters[i][j][1],
            "cluster": i
          });
        }
      }
      updatePlot(newData);
    });

    function updatePlot(newData) {
      var svg = d3.select("#plot");
      var circles = svg.selectAll("circle")
        .data(newData);
      circles.enter()
        .append("circle")
        .attr("cx", function(d) { return d.x * 50; })
        .attr("cy", function(d) { return d.y * 50; })
        .attr("r", 5)
        .style("fill", function(d) { return d3.schemeCategory10[d.cluster]; });
      circles.exit().remove();
    }
  </script>
</head>
<body>
  <div id="plot"></div>
</body>
</html>
In this example, the k-means clustering algorithm is used to group the data points into three clusters. The resulting clustered data points are then visualized in a scatterplot using D3.js, with each cluster represented by a different color. Users can explore the data by hovering over the data points to see which cluster they belong to.

