    for (let i = 2; i <= Math.sqrt(num); i++) {
      if (num % i === 0) return false;
    }
    return true;
  };
  const primeNumbers = [];
  const primeNumbersUpToIndex = [];
  for (let i = 0; i < inputString.length; i++) {
    let sum = 0;
    for (let j = i; j < inputString.length; j++) {
      sum += inputString.charCodeAt(j);
      if (isPrime(sum)) {
        primeNumbers.push(sum);
      }
    }
    primeNumbersUpToIndex.push(primeNumbers.slice());
  }
  return primeNumbersUpToIndex;
}
```
To implement memoization, we can store the results of each substring in a cache object and check if the result has already been computed before computing it again:
```
function findPrimeNumbers(inputString) {
  const isPrime = num => {
    if (num <= 1) return false;
    for (let i = 2; i <= Math.sqrt(num); i++) {
      if (num % i === 0) return false;
    }
    return true;
  };
  const primeNumbers = [];
  const primeNumbersUpToIndex = [];
  const cache = {};
  for (let i = 0; i < inputString.length; i++) {
    let sum = 0;
    for (let j = i; j < inputString.length; j++) {
      sum += inputString.charCodeAt(j);
      if (cache[sum]) {
        primeNumbers.push(...cache[sum]);
      } else if (isPrime(sum)) {
        primeNumbers.push(sum);
        if (!cache[sum]) {
          cache[sum] = [sum];
        }
      }
    }
    primeNumbersUpToIndex.push(primeNumbers.slice());
  }
  return primeNumbersUpToIndex;
}
