This strategy involves simply accepting the changes made by one party and discarding the changes made by the other party. The code below shows how to implement this strategy in C++:
```c++
void resolve_conflict_strategy_1(string& my_text, string& other_text) {
    //Accepting changes made by other party
    //my_text will now be the same as other_text
    my_text = other_text;
}
```
Strategy 2: Merging changes made by both parties
This strategy involves merging the changes made by both parties into a single document. The code below shows how to implement this strategy in C++:
```c++
void resolve_conflict_strategy_2(string& my_text, string& other_text) {
    //Splitting my_text into words
    vector<string> my_words;
    stringstream my_stream(my_text);
    string word;
    while (my_stream >> word) {
        my_words.push_back(word);
    }
    //Splitting other_text into words
    vector<string> other_words;
    stringstream other_stream(other_text);
    while (other_stream >> word) {
        other_words.push_back(word);
    }
    //Merging the two sets of words into a single string
    string merged_text = "";
    int i = 0, j = 0;
    while (i < my_words.size() && j < other_words.size()) {
        if (my_words[i] == other_words[j]) {
            merged_text += my_words[i] + " ";
            i++;
            j++;
        } else {
            merged_text += my_words[i] + " " + other_words[j] + " ";
            i++;
            j++;
        }
    }
    while (i < my_words.size()) {
        merged_text += my_words[i] + " ";
        i++;
    }
    while (j < other_words.size()) {
        merged_text += other_words[j] + " ";
        j++;
    }
    //Setting my_text to the merged_text
    my_text = merged_text;
}
```
Strategy 3: Prompting the user to manually resolve the conflict
This strategy involves prompting the user to manually choose which version of the document to keep. The code below shows how to implement this strategy in C++:
