let searchURL = URL(string: "https://api.themoviedb.org/3/discover/movie?api_key=\(apiKey)&with_genres=\(genre)&certification_country=US&certification=\(rating)")!
// Create the URLSession
let session = URLSession.shared
// Create the data task for the search URL
let task = session.dataTask(with: searchURL) { (data, response, error) in
    // Check for errors
    guard error == nil else {
        print("Error: \(error!)")
        return
    }

    // Check for a successful response
    guard let response = response as? HTTPURLResponse, (200...299).contains(response.statusCode) else {
        print("Error: Invalid response")
        return
    }

    // Check for data
    guard let data = data else {
        print("Error: No data")
        return
    }

    // Parse the JSON data
    do {
        let json = try JSONSerialization.jsonObject(with: data, options: [])
        guard let movies = json["results"] as? [[String:Any]] else {
            print("Error: Invalid JSON data")
            return
        }

        // Extract the movie information
        for movie in movies {
            guard let title = movie["title"] as? String,
                  let releaseDate = movie["release_date"] as? String,
                  let overview = movie["overview"] as? String else {
                print("Error: Missing movie information")
                continue
            }

            print("Title: \(title)")
            print("Release Date: \(releaseDate)")
            print("Overview: \(overview)")
        }
    } catch {
        print("Error: \(error)")
    }
}
// Start the data task
task.resume()
```
