```python
import spacy
nlp = spacy.load("en_core_web_sm")
sentence = "Heard from the mountain top, the bird's song is a beautiful melody."
doc = nlp(sentence)
# Check subject-verb agreement
for token in doc:
    if token.dep_ == "nsubj" and token.head.pos_ == "VERB":
        if token.tag_ != token.head.tag_:
            print("Subject-verb agreement error:", token.text, token.tag_, "->", token.head.text, token.head.tag_)
# Check noun-pronoun agreement
for token in doc:
    if token.pos_ == "PRON" and token.head.pos_ == "NOUN":
        if token.tag_ != token.head.tag_:
            print("Noun-pronoun agreement error:", token.text, token.tag_, "->", token.head.text, token.head.tag_)
# Check tense consistency
for token in doc:
    if token.tag_.startswith("V"):
        for child in token.children:
            if child.dep_ in ["aux", "auxpass"]:
                if child.tag_ != token.tag_:
                    print("Tense consistency error:", child.text, child.tag_, "->", token.text, token.tag_)
# Check idiomatic expressions
idioms = [("heard from", "heard on"), ("mountain top", "mountaintop"), ("bird's song", "birdsong")]
for idiom in idioms:
    if idiom[0] in sentence:
        sentence = sentence.replace(idiom[0], idiom[1])
        print("Idiomatic expression corrected:", idiom[0], "->", idiom[1])
print("Corrected sentence:", sentence)
```
