        for (int i = 0; i < n; i++)
        {
            if (matrix[i,i] == 0)
            {
                Console.WriteLine("No unique solution exists.");
                return;
            }
            for (int j = i + 1; j < n; j++)
            {
                double factor = matrix[j,i] / matrix[i,i];
                for (int k = i; k < n + 1; k++)
                {
                    matrix[j,k] -= factor * matrix[i,k];
                }
            }
        }
        // Back substitution
        double[] solution = new double[n];
        for (int i = n - 1; i >= 0; i--)
        {
            double sum = 0;
            for (int j = i + 1; j < n; j++)
            {
                sum += matrix[i,j] * solution[j];
            }
            solution[i] = (matrix[i,n] - sum) / matrix[i,i];
        }
        // Printing the solution
        Console.WriteLine("The values of x, y, and z are: {0}, {1}, {2}", solution[0], solution[1], solution[2]);
    }
}
```
The program first initializes the matrix with the coefficients and constants of the equations. It then applies Gaussian Elimination to reduce the matrix to an upper triangular form. If a pivot element is zero, the program stops and reports that no unique solution exists. If the matrix is successfully reduced, the program performs back substitution to obtain the values of x, y, and z. Finally, the program prints the solution.

