  "B": {"C": 1, "D": 2},
  "C": {"B": 4, "D": 8, "E": 2},
  "D": {"E": 7},
  "E": {"D": 9}
};
const start = "A";
const end = "D";
console.log(dijkstra(cities, start, end)); // Output: ["A", "C", "E", "D"]
```

