To analyze the level of anthropomorphism in a given statement, you can use natural language processing techniques to identify and classify the language used in the statement. Here's a sample algorithm that you can use:
1. Tokenize the statement into individual words.
2. Identify the nouns and pronouns in the statement.
3. Use a part-of-speech tagger to identify the verbs and adjectives in the statement.
4. Use a sentiment analysis tool to determine the overall sentiment of the statement.
5. Identify any anthropomorphic language in the statement, such as personification, anthropomorphization, or animalization.
6. Assign a score to the statement based on the level of anthropomorphism detected.
Here's a sample code in C++ that uses the Stanford CoreNLP library to perform some of these tasks:
```cpp
#include <iostream>
#include <vector>
#include <string>
#include "stanford-corenlp/cpp/CoreNLP.h"
using namespace std;
using namespace CoreNLP;
int main() {
    // Create a StanfordCoreNLP object with the default properties file
    StanfordCoreNLP pipeline;
    // Set up a text to analyze
    string text = "My pet hedgehog insists on choosing his own outfits";
    // Annotate the text with part-of-speech tags and sentiment analysis
    auto annotation = pipeline.annotate(text, {"pos", "sentiment"});
    // Get the list of sentences in the annotation
    auto sentences = annotation.get< vector<Sentence> >("sentences");
    // Loop through each sentence in the annotation
    for (auto sentence : sentences) {
        // Get the list of tokens in the sentence
        auto tokens = sentence.get< vector<Token> >("tokens");
        // Loop through each token in the sentence
        for (auto token : tokens) {
            // Get the part-of-speech tag for the token
            auto pos = token.get<string>("pos");
            // If the token is a noun or pronoun, check for anthropomorphic language
            if (pos == "NN" || pos == "NNS" || pos == "NNP" || pos == "PRP") {
                // Get the word text for the token
                auto word = token.word();
                // Check for anthropomorphic language
                if (word == "pet" || word == "insists" || word == "choosing" || word == "outfits") {
                    // Increase the score for the statement
                    score++;
                }
            }
        }
        // Get the sentiment score for the sentence
        auto sentiment = sentence.sentiment();
        // Add the sentiment score to the overall score for the statement
        score += sentiment;
    }
    // Print the overall score for the statement
    cout << "Anthropomorphism score: " << score << endl;
    return 0;
}
```
Note that this is just a sample algorithm and code, and you may need to customize it to suit your specific needs and requirements.

